package eval

func equipmentAndAttunementSuite() Suite {
	base := inventoryStacksSuite()
	return Suite{ID: "055-equipment-and-attunement", Name: "Campaign Play 055: Equipment and Attunement", Tests: append(base.Tests,
		playTest("play-inventory-add-leather-armor", "Owner provisions leather armor through inventory", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "leather-armor", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "leather-armor", "quantity": 1, "total_quantity": 1}),
		playTest("play-inventory-add-ring-protection", "Owner provisions an attunable ring through inventory", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "ring-of-protection", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "ring-of-protection", "quantity": 1, "total_quantity": 1}),
		playTest("play-inventory-add-amulet-health", "Owner provisions an attunable amulet through inventory", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "amulet-of-health", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "amulet-of-health", "quantity": 1, "total_quantity": 1}),
		playTest("play-equip-non-owner", "Non-owner cannot equip a character item", "PUT", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/armor", map[string]any{"item_id": "leather-armor"}, map[string]string{"Authorization": playerBAuth}, 403, nil),
		playTest("play-equip-invalid-slot", "Equipment rejects unknown slots", "PUT", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/weapon", map[string]any{"item_id": "leather-armor"}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-equip-slot-mismatch", "Equipment rejects items in the wrong legal slot", "PUT", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/armor", map[string]any{"item_id": "ring-of-protection"}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-equip-leather-armor", "Owner equips leather armor", "PUT", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/armor", map[string]any{"item_id": "leather-armor"}, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "slot": "armor", "item_id": "leather-armor", "attuned": false}),
		playTest("play-equipment-read-member", "Campaign member can read character equipment", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/armor", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-w", "slot": "armor", "item_id": "leather-armor", "attuned": false}),
		playTest("play-equip-ring-protection", "Owner equips an attunable accessory", "PUT", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/accessory", map[string]any{"item_id": "ring-of-protection"}, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "slot": "accessory", "item_id": "ring-of-protection", "attuned": false}),
		playTest("play-attune-non-owner", "Non-owner cannot attune a character item", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/accessory/attune", nil, map[string]string{"Authorization": playerBAuth}, 403, nil),
		playTest("play-attune-ring-protection", "Owner attunes an equipped ring", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/accessory/attune", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "slot": "accessory", "item_id": "ring-of-protection", "attuned": true, "attunement_count": 1, "max_attunements": 1}),
		playTest("play-attune-cap-conflict", "A second attunement is rejected at the cap", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/equipment/accessory/attune", nil, map[string]string{"Authorization": playerAAuth}, 409, nil),
	)}
}
